import{az as a,P as e,Q as r,aQ as l}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"框架/跨端/index.md","filePath":"框架/跨端/index.md","lastUpdated":1785339991000}'),n={name:"框架/跨端/index.md"};function s(o,t,d,i,p,c){return e(),r("div",null,[...t[0]||(t[0]=[l(`<h2 id="跨端开发概述" tabindex="-1">跨端开发概述 <a class="header-anchor" href="#跨端开发概述" aria-label="Permalink to “跨端开发概述”">​</a></h2><p>跨端开发指用<strong>一套代码</strong>同时构建多个平台应用（Web、iOS、Android、桌面、小程序）。它解决了多端重复开发成本高、迭代慢、体验不一致的问题。不同方案在渲染机制、性能、生态上各有取舍。</p><h2 id="主流跨端方案对比" tabindex="-1">主流跨端方案对比 <a class="header-anchor" href="#主流跨端方案对比" aria-label="Permalink to “主流跨端方案对比”">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>渲染机制</th><th>性能</th><th>生态</th><th>适用端</th></tr></thead><tbody><tr><td>React Native</td><td>原生组件</td><td>高</td><td>大</td><td>iOS/Android</td></tr><tr><td>Flutter</td><td>自绘引擎</td><td>高</td><td>增长快</td><td>iOS/Android/Web/桌面</td></tr><tr><td>Electron</td><td>Chromium + Node</td><td>中</td><td>大</td><td>桌面</td></tr><tr><td>Taro</td><td>编译到各端原生</td><td>中</td><td>国内大</td><td>小程序/H5/RN</td></tr><tr><td>uni-app</td><td>编译到各端原生</td><td>中</td><td>国内大</td><td>小程序/H5/App</td></tr><tr><td>Ionic</td><td>WebView + Capacitor</td><td>中</td><td>大</td><td>H5/移动 App</td></tr><tr><td>Weex</td><td>原生渲染</td><td>中</td><td>衰退</td><td>iOS/Android</td></tr></tbody></table><h2 id="渲染机制分类" tabindex="-1">渲染机制分类 <a class="header-anchor" href="#渲染机制分类" aria-label="Permalink to “渲染机制分类”">​</a></h2><h3 id="原生渲染" tabindex="-1">原生渲染 <a class="header-anchor" href="#原生渲染" aria-label="Permalink to “原生渲染”">​</a></h3><p>把 JS 编写的 UI 映射到平台原生组件，性能接近原生。代表：React Native、Weex。</p><h3 id="自绘渲染" tabindex="-1">自绘渲染 <a class="header-anchor" href="#自绘渲染" aria-label="Permalink to “自绘渲染”">​</a></h3><p>自带渲染引擎（Skia / Impeller），直接绘制到画布，跨端一致性好。代表：Flutter。</p><h3 id="webview-混合" tabindex="-1">WebView 混合 <a class="header-anchor" href="#webview-混合" aria-label="Permalink to “WebView 混合”">​</a></h3><p>用 WebView 加载 H5，再通过桥接调用原生能力。代表：Ionic、Cordova。</p><h3 id="编译式多端" tabindex="-1">编译式多端 <a class="header-anchor" href="#编译式多端" aria-label="Permalink to “编译式多端”">​</a></h3><p>把统一 DSL 编译到各端原生代码，适合小程序生态。代表：Taro、uni-app。</p><h2 id="选型决策" tabindex="-1">选型决策 <a class="header-anchor" href="#选型决策" aria-label="Permalink to “选型决策”">​</a></h2><ul><li><strong>桌面应用</strong>：Electron（Web 技术栈）或 Tauri（Rust 内核更轻量）。</li><li><strong>高性能移动 App</strong>：Flutter（自绘一致）或 React Native（原生体验）。</li><li><strong>国内小程序 + H5 + App 全覆盖</strong>：Taro 或 uni-app。</li><li><strong>混合 H5 套壳</strong>：Ionic + Capacitor。</li><li><strong>游戏类跨端</strong>：Cocos / Unity（非前端栈）。</li></ul><h2 id="架构共性" tabindex="-1">架构共性 <a class="header-anchor" href="#架构共性" aria-label="Permalink to “架构共性”">​</a></h2><p>跨端框架通常包含三部分：</p><ol><li><strong>UI 层</strong>：声明式组件描述（JSX / Widget / Template）。</li><li><strong>桥接层（Bridge）</strong>：把 UI 指令与原生 API 调用转发到各平台。</li><li><strong>原生层</strong>：各平台原生组件 / 自绘引擎执行渲染。</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 跨端架构示意</span></span>
<span class="line"><span style="color:#FFCB6B;">JS/TS</span><span style="color:#C3E88D;"> 业务代码</span></span>
<span class="line"><span style="color:#FFCB6B;">   -</span><span style="color:#BABED8;">&gt; </span><span style="color:#C3E88D;">框架运行时（React/Vue/Flutter</span><span style="color:#C3E88D;"> Engine）</span></span>
<span class="line"><span style="color:#FFCB6B;">   -</span><span style="color:#BABED8;">&gt; </span><span style="color:#C3E88D;">Bridge（JS</span><span style="color:#89DDFF;"> &lt;</span><span style="color:#BABED8;">-</span><span style="color:#89DDFF;">&gt;</span><span style="color:#C3E88D;"> Native</span><span style="color:#C3E88D;"> 序列化）</span></span>
<span class="line"><span style="color:#FFCB6B;">   -</span><span style="color:#BABED8;">&gt; </span><span style="color:#C3E88D;">原生渲染（iOS</span><span style="color:#C3E88D;"> UIKit</span><span style="color:#C3E88D;"> /</span><span style="color:#C3E88D;"> Android</span><span style="color:#C3E88D;"> View</span><span style="color:#C3E88D;"> /</span><span style="color:#C3E88D;"> Skia）</span></span></code></pre></div><h2 id="性能与体验权衡" tabindex="-1">性能与体验权衡 <a class="header-anchor" href="#性能与体验权衡" aria-label="Permalink to “性能与体验权衡”">​</a></h2><ul><li>自绘方案（Flutter）一致性最好，但包体积大。</li><li>原生映射方案（RN）体验好，但 bridge 通信有开销。</li><li>WebView 方案开发快，但性能与原生差距明显。</li><li>编译式方案（Taro）多端覆盖广，但需适配各端差异。</li></ul><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to “参考”">​</a></h2><ul><li><a href="https://flutter.dev/" target="_blank" rel="noreferrer">Flutter 官网</a></li><li><a href="https://reactnative.dev/" target="_blank" rel="noreferrer">React Native 官网</a></li><li><a href="https://docs.taro.zone/" target="_blank" rel="noreferrer">Taro 文档</a></li><li><a href="https://juejin.cn/post/6844904193964945415" target="_blank" rel="noreferrer">跨端开发选型对比</a></li></ul>`,23)])])}const y=a(n,[["render",s]]);export{g as __pageData,y as default};
